-- BullPen Academy — course: "Portfolio Risk & Correlation" (advanced, Pro)
-- Hand-authored + Zod-validated (scripts/_author_phase3.ts). Re-runnable: ON CONFLICT DO NOTHING.

INSERT INTO academy_courses (slug, title, description, icon, color, order_index, difficulty, requires_pro, is_published) VALUES
  ('portfolio-risk', 'Portfolio Risk & Correlation', 'Risk is more than a bouncy price. Learn what beta, correlation, and drawdown really measure — and how concentration and position sizing decide whether your portfolio survives a bad year.', 'ShieldAlert', 'amber', 10, 'advanced', TRUE, TRUE)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT
  (SELECT id FROM academy_courses WHERE slug = 'portfolio-risk'),
  v.slug, v.title, v.type, v.order_index, v.xp_reward, v.content
FROM (VALUES
  ('risk-is-not-volatility', 'Risk Isn’t Just Volatility', 'read', 0, 10, '{"sections":[{"text":"When people call a stock “risky,” they usually mean its price bounces around a lot. That’s volatility — often measured as standard deviation, or how far returns stray from their average. It’s real, but it’s only one face of risk, and not the one that hurts most.","highlightedTerms":[{"term":"Volatility","definition":"How much a price swings up and down over time. High volatility means bigger, faster moves in both directions."}]},{"text":"Beta measures a different thing: how much a stock tends to move relative to the whole market. A beta of 1 moves with the market, 1.5 swings about 50% harder, and below 1 is steadier. It tells you how much of the market’s risk a stock adds to your portfolio.","highlightedTerms":[{"term":"Beta","definition":"How much this stock moves compared to the overall market. Beta > 1 means it swings more than the market; < 1 means it''s calmer."}]},{"text":"The risk that actually damages wealth is drawdown — how far an investment falls from a peak to its lowest point. And the math is cruel: a 50% drawdown needs a 100% gain just to get back to even. Avoiding deep holes matters more than chasing big returns.","highlightedTerms":[{"term":"Max Drawdown","definition":"The largest peak-to-trough drop an investment suffers. A 50% drawdown requires a 100% gain to recover."}]},{"text":"So the real definition of risk isn’t day-to-day wiggle — it’s the permanent loss of capital. A volatile stock you understand and can hold through a dip may be far safer than a “stable” one quietly heading to zero.","highlightedTerms":[]}],"funFact":"Losses and gains aren’t symmetric: down 50% then up 50% leaves you at 75, not 100. That asymmetry is exactly why professionals obsess over limiting drawdowns."}'::jsonb),
  ('correlation', 'Correlation & Why It Matters', 'read', 1, 10, '{"sections":[{"text":"Diversification is often called the only free lunch in investing — but it only works if your holdings don’t all move together. Correlation measures exactly that: +1 means two stocks move in lockstep, 0 means unrelated, and −1 means they move in opposite directions.","highlightedTerms":[{"term":"Correlation","definition":"A measure of how two investments move together. +1 = perfectly in sync, 0 = unrelated, −1 = opposite. Low correlation is what makes diversification work."}]},{"text":"Here’s the catch that fools people: owning ten technology stocks feels diversified, but it isn’t. They’re highly correlated — one tech selloff drags them all down at once. Real diversification mixes things that react differently to the same news.","highlightedTerms":[]},{"text":"That’s why spreading across sectors and asset types helps. When stocks fall, bonds or gold may hold steady or even rise, cushioning the blow. Low correlation between holdings is what smooths the overall ride.","highlightedTerms":[{"term":"Asset Allocation","definition":"How you split a portfolio across different types of assets — stocks, bonds, cash, commodities — to balance risk and return."}]},{"text":"The goal was never to eliminate risk — it’s to avoid stacking all your risk in one place. A basket of genuinely uncorrelated bets is more resilient than the sum of its parts.","highlightedTerms":[]}],"funFact":"In the 2008 crash, many “diversified” portfolios fell together anyway — correlations spiked toward +1 as panic hit everything at once. Correlation isn’t fixed; it can rise exactly when you need it low."}'::jsonb),
  ('concentration-position-sizing', 'Concentration & Position Sizing', 'read', 2, 10, '{"sections":[{"text":"How much of your portfolio sits in a single stock is called position sizing, and it quietly decides your fate. A 40% position in one name means that one company alone can make or break your whole result — no matter how good your other picks are.","highlightedTerms":[{"term":"Position Sizing","definition":"How much of your portfolio you put into a single holding. It often matters as much as which stocks you pick."}]},{"text":"Concentration is the flip side of diversification: too few holdings, or one that has grown huge. Even a wonderful stock that ballooned to half your portfolio has become a concentration risk — a single point of failure.","highlightedTerms":[{"term":"Concentration Risk","definition":"The danger of having too much of your portfolio riding on one stock, sector, or bet — so a single bad outcome does outsized damage."}]},{"text":"Rebalancing is the discipline that fights it: periodically trimming what has grown too large and topping up what has lagged, back toward your target weights. It quietly forces you to sell high and buy low, and keeps any one position from taking over.","highlightedTerms":[{"term":"Rebalancing","definition":"Adjusting a portfolio back to its target weights — trimming winners and adding to laggards — to keep risk under control."}]},{"text":"There’s no magic number, but a common guardrail is keeping any single stock under roughly 5–10% of the portfolio. The right figure depends on your risk tolerance; the real point is to size positions on purpose, not by accident.","highlightedTerms":[{"term":"Risk Tolerance","definition":"How much volatility and potential loss you can stomach — financially and emotionally — without abandoning your plan."}]}],"funFact":"Many professional funds are legally barred from putting more than a set percentage in any one stock — a hard rule that exists purely to limit concentration risk."}'::jsonb),
  ('risk-quiz', 'Quick Check: Portfolio Risk', 'quiz', 3, 20, '{"questions":[{"question":"A stock has a beta of 1.5. If the overall market rises 10%, roughly how much would you expect this stock to move?","options":["About 1.5%","About 10%","About 15%","It can’t be estimated"],"correctIndex":2,"explanation":"Beta scales market moves: 1.5 × 10% ≈ 15%. A beta above 1 amplifies both the market’s gains and its losses."},{"question":"Two stocks you own have a correlation close to +1. What does that mean for your diversification?","options":["They move together, so holding both adds little diversification","They move oppositely, cancelling each other out","They’re unrelated, giving strong diversification","One of them must be a bond"],"correctIndex":0,"explanation":"A correlation near +1 means the two rise and fall together, so owning both barely reduces risk — you effectively have one bigger bet."},{"question":"An investment falls from a peak of $100 to $50. What gain from $50 is needed just to get back to $100?","options":["50%","75%","100%","150%"],"correctIndex":2,"explanation":"Recovering from a 50% loss takes a 100% gain ($50 → $100). Losses and gains aren’t symmetric, which is why big drawdowns are so costly."},{"question":"Your best-performing stock has quietly grown to 45% of your portfolio. What does rebalancing suggest?","options":["Buy even more, since it’s winning","Trim it back toward your target weight to reduce concentration risk","Sell everything else instead","Nothing — position size doesn’t matter"],"correctIndex":1,"explanation":"A 45% position is a concentration risk. Rebalancing trims the oversized winner back toward its target so one stock can’t dominate your outcome."}]}'::jsonb),
  ('risk-match', 'Match the Risk Metrics', 'match', 4, 15, '{"pairs":[{"term":"Beta","definition":"How much a stock moves relative to the overall market."},{"term":"Correlation","definition":"Whether two holdings move together, oppositely, or independently."},{"term":"Max Drawdown","definition":"The largest drop from a peak to a trough."},{"term":"Position Sizing","definition":"How much of a portfolio a single holding represents."},{"term":"Rebalancing","definition":"Trimming winners and topping up laggards back to target weights."}]}'::jsonb),
  ('stress-test-demo', 'Stress-Test a Portfolio', 'demo', 5, 25, '{"surface":"demo-portfolio","fixtureId":"concentrated-tech","steps":[{"id":"intro","target":"none","title":"A risky portfolio, on purpose","body":"This sample portfolio was built to show what risk looks like. On a green day it seems fine — but the danger is in how the money is distributed. Let’s find it.","requiredAction":"none"},{"id":"overview","target":"portfolio-overview","title":"Totals hide the risk","body":"The header totals up value and today’s move like any portfolio. But a single number can’t show you where the risk is concentrated — you have to look underneath.","requiredAction":"none"},{"id":"concentration","target":"largest-position","title":"Concentration risk","body":"Look at the biggest position: roughly 70% of the entire portfolio sits in one stock. That single company will make or break this account — the definition of concentration risk.","requiredAction":"none"},{"id":"correlation","target":"allocation-chart","title":"Correlation risk","body":"Now the breakdown: almost everything is in one sector. These holdings are highly correlated — one industry selloff drags them all down together. This is the opposite of diversification.","requiredAction":"none"},{"id":"wrap","target":"none","title":"You can spot it now","body":"One dominant position, one sector, nothing uncorrelated to cushion a fall. A resilient portfolio spreads across uncorrelated bets in sensible sizes — and you can now diagnose one that doesn’t.","requiredAction":"none"}]}'::jsonb),
  ('rebalance-or-hold', 'Rebalance or Hold?', 'scenario', 6, 25, '{"setup":"A year ago you built a balanced portfolio with no position over 10%. One stock has since tripled and now makes up 38% of everything you own. You still love the company and its story hasn’t changed. Your gut says “winners keep winning — let it ride.” What’s the disciplined move?","choices":[{"label":"Let it ride — it’s a great company and winners keep winning. Selling would just cap the upside.","feedback":"The company may well keep winning, but that’s not the point. At 38% of your portfolio, a single stumble in this one name now dictates your whole result — that’s exactly the concentration risk you built the portfolio to avoid. Loving a company isn’t a risk-management plan.","isCorrect":false},{"label":"Trim it back toward your target weight, taking some profit and spreading it into your other positions.","feedback":"Exactly. Rebalancing here isn’t doubting the company — it’s refusing to let one bet dominate your outcome. You lock in some gains, cut the single-point-of-failure risk, and keep the discipline that made the portfolio resilient in the first place.","isCorrect":true},{"label":"Sell the entire position and move fully to cash to be safe.","feedback":"That over-corrects. Dumping a good holding entirely — and sitting in cash — trades concentration risk for the risk of missing the market and abandoning your plan. Rebalancing is about trimming to a sensible size, not fleeing altogether.","isCorrect":false}]}'::jsonb)
) AS v(slug, title, type, order_index, xp_reward, content)
ON CONFLICT (course_id, slug) DO NOTHING;
